CREATE TABLE IF NOT EXISTS settings (id text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO settings(id,value) VALUES ('global','{"paused":false,"preset":"quarter","version":1}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY,email text UNIQUE NOT NULL,role text NOT NULL DEFAULT 'advertiser' CHECK(role IN ('advertiser','admin')),suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,account_id text REFERENCES accounts(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS challenges (email text PRIMARY KEY,code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS drafts (id text PRIMARY KEY,owner_token text NOT NULL,account_id text REFERENCES accounts(id),data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assets (id text PRIMARY KEY,account_id text REFERENCES accounts(id),owner_token text NOT NULL,path text NOT NULL,public boolean NOT NULL DEFAULT false,bytes integer NOT NULL CHECK(bytes>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brands (id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),name text NOT NULL,suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS creatives (id text PRIMARY KEY,brand_id text NOT NULL REFERENCES brands(id),data jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reason text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS slots (id text PRIMARY KEY,opening integer NOT NULL CHECK(opening>=100),available boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,leader_brand text REFERENCES brands(id),creative_id text REFERENCES creatives(id));
CREATE TABLE IF NOT EXISTS totals (slot_id text NOT NULL REFERENCES slots(id),brand_id text NOT NULL REFERENCES brands(id),amount integer NOT NULL DEFAULT 0 CHECK(amount>=0),creative_id text REFERENCES creatives(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(slot_id,brand_id));
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),brand_id text NOT NULL REFERENCES brands(id),creative_id text NOT NULL REFERENCES creatives(id),slot_id text NOT NULL REFERENCES slots(id),slot_version integer NOT NULL,existing integer NOT NULL CHECK(existing>=0),target integer NOT NULL CHECK(target>0),due integer NOT NULL CHECK(due>0),rules jsonb NOT NULL,mode text NOT NULL,product_id text NOT NULL,business_id text NOT NULL,customer_id text,customer_email text NOT NULL,state text NOT NULL DEFAULT 'reserved',session_id text UNIQUE,checkout_url text,reserved boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL,cutoff_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(target=existing+due));
CREATE UNIQUE INDEX IF NOT EXISTS one_reservation_per_slot ON orders(slot_id) WHERE reserved=true;
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),principal integer NOT NULL CHECK(principal>=0),tax integer NOT NULL CHECK(tax>=0),cash integer NOT NULL CHECK(cash>=0),refunded integer NOT NULL DEFAULT 0 CHECK(refunded>=0),refunded_cash integer NOT NULL DEFAULT 0 CHECK(refunded_cash>=0),disputed boolean NOT NULL DEFAULT false,state text NOT NULL,evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS allocations (payment_id text PRIMARY KEY REFERENCES payments(id),slot_id text NOT NULL REFERENCES slots(id),brand_id text NOT NULL REFERENCES brands(id),amount integer NOT NULL CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS history (id text PRIMARY KEY,slot_id text NOT NULL REFERENCES slots(id),brand_id text REFERENCES brands(id),creative_id text REFERENCES creatives(id),payment_id text REFERENCES payments(id),total integer NOT NULL CHECK(total>=0),kind text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_placement ON history(slot_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS webhook_events (id text PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE IF NOT EXISTS refunds (id text PRIMARY KEY,payment_id text NOT NULL REFERENCES payments(id),provider_id text UNIQUE,state text NOT NULL,reason text NOT NULL,amount integer,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_refund ON refunds(payment_id) WHERE state IN ('queued','sending','pending','ambiguous','review');
CREATE TABLE IF NOT EXISTS disputes (id text PRIMARY KEY,payment_id text NOT NULL REFERENCES payments(id),status text NOT NULL,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'ready',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),leased_until timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ready_jobs ON jobs(state,available_at);
CREATE TABLE IF NOT EXISTS audit (id text PRIMARY KEY,actor text,action text NOT NULL,target text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics (day date NOT NULL DEFAULT CURRENT_DATE,slot_id text NOT NULL,creative_id text NOT NULL DEFAULT 'house',kind text NOT NULL,visitor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(day,slot_id,creative_id,kind,visitor));
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id text PRIMARY KEY,slot_id text NOT NULL REFERENCES slots(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
